function Get-Prop($Object,[string]$Name) {
 if ($null -eq $Object) { return $null }
 $p=$Object.PSObject.Properties[$Name]
 if ($null -ne $p) { return $p.Value }
 return $null
}
function Write-JsonFile($Object,[string]$Path) {
 [IO.File]::WriteAllText($Path,($Object | ConvertTo-Json -Depth 100),$Utf8)
 $bytes=[IO.File]::ReadAllBytes($Path)
 if ($bytes.Length -ge 3 -and $bytes[0] -eq 239 -and $bytes[1] -eq 187 -and $bytes[2] -eq 191) { throw 'Unexpected UTF-8 BOM.' }
}
function Get-Sha256([string]$Path) { (Get-FileHash -LiteralPath $Path -Algorithm SHA256).Hash.ToLowerInvariant() }
function Invoke-Gh([string[]]$GhArgs,[switch]$Allow404) {
 $out=Join-Path $OutputDir 'gh.stdout.tmp'
 $err=Join-Path $OutputDir 'gh.stderr.tmp'
 $p=Start-Process -FilePath $GhExe -ArgumentList $GhArgs -WindowStyle Hidden -Wait -PassThru -RedirectStandardOutput $out -RedirectStandardError $err
 $stdout=[IO.File]::ReadAllText($out,$Utf8)
 $stderr=[IO.File]::ReadAllText($err,$Utf8)
 if ($p.ExitCode -ne 0) {
  if ($Allow404 -and $stderr -match 'HTTP\s+404') { return $null }
  throw "GitHub request failed (exit=$($p.ExitCode)); no continuation."
 }
 return ($stdout | ConvertFrom-Json)
}
function Test-RemoteAbsent {
 $remote=Invoke-Gh -GhArgs @('api',"repos/$Repo/contents/$RawResultRepoPath") -Allow404
 if ($null -ne $remote) { throw 'Raw _008 already exists; refusing rerun or overwrite.' }
}
function Test-ComfyReady {
 try { $null=Invoke-RestMethod "$ComfyBase/system_stats" -TimeoutSec 3; return $true } catch { return $false }
}
function Start-Comfy {
 if (-not (Test-ComfyReady)) {
  $args=@('-s',('"' + $ComfyMain + '"'),'--windows-standalone-build','--listen','127.0.0.1','--port','8188','--disable-auto-launch')
  $script:ComfyProcess=Start-Process -FilePath $PythonExe -ArgumentList $args -WorkingDirectory $ComfyRoot -WindowStyle Hidden -PassThru -RedirectStandardOutput (Join-Path $OutputDir 'comfy.stdout.log') -RedirectStandardError (Join-Path $OutputDir 'comfy.stderr.log')
  $watch=[Diagnostics.Stopwatch]::StartNew()
  while ($watch.Elapsed.TotalSeconds -lt 120) {
   if (Test-ComfyReady) { break }
   if ($script:ComfyProcess.HasExited) { throw 'ComfyUI exited during startup.' }
   Start-Sleep -Milliseconds 500
  }
  if (-not (Test-ComfyReady)) { throw 'ComfyUI startup timeout.' }
 }
 $stats=Invoke-RestMethod "$ComfyBase/system_stats" -TimeoutSec 5
 if ((Get-Prop (Get-Prop $stats 'system') 'comfyui_version') -cne '0.39.0') { throw 'Live ComfyUI server version differs from 0.39.0.' }
 $q=Invoke-RestMethod "$ComfyBase/queue" -TimeoutSec 5
 if ($null -eq $q.PSObject.Properties['queue_running'] -or $null -eq $q.PSObject.Properties['queue_pending']) { throw 'Queue state unknown.' }
 if (@(Get-Prop $q 'queue_running').Count -gt 0 -or @(Get-Prop $q 'queue_pending').Count -gt 0) { throw 'ComfyUI queue is not empty.' }
}
function Invoke-Cdp([string]$Method,[hashtable]$Params) {
 $script:CdpId++
 $cancel=[Threading.CancellationTokenSource]::new(30000)
 try {
  $bytes=$Utf8.GetBytes((@{id=$script:CdpId;method=$Method;params=$Params} | ConvertTo-Json -Depth 50 -Compress))
  $null=$script:Socket.SendAsync([ArraySegment[byte]]::new($bytes),[Net.WebSockets.WebSocketMessageType]::Text,$true,$cancel.Token).GetAwaiter().GetResult()
  while ($true) {
   $stream=[IO.MemoryStream]::new()
   try {
    do {
     $buf=New-Object byte[] 65536
     $recv=$script:Socket.ReceiveAsync([ArraySegment[byte]]::new($buf),$cancel.Token).GetAwaiter().GetResult()
     if ($recv.MessageType -eq [Net.WebSockets.WebSocketMessageType]::Close) { throw 'CDP socket closed.' }
     $stream.Write($buf,0,$recv.Count)
    } until ($recv.EndOfMessage)
    $msg=$Utf8.GetString($stream.ToArray()) | ConvertFrom-Json
    $id=Get-Prop $msg 'id'
    if ($null -ne $id -and [int]$id -eq $script:CdpId) {
     if ($null -ne (Get-Prop $msg 'error')) { throw 'CDP protocol error.' }
     return $msg
    }
   } finally { $stream.Dispose() }
  }
 } finally { $cancel.Dispose() }
}
function Invoke-Js([string]$Expression) {
 $r=Invoke-Cdp 'Runtime.evaluate' @{expression=$Expression;returnByValue=$true;awaitPromise=$true}
 $evaluation=Get-Prop $r 'result'
 if ($null -eq $evaluation) { throw 'CDP missing result.' }
 if ($null -ne (Get-Prop $evaluation 'exceptionDetails')) { throw 'Browser compilation exception.' }
 $remote=Get-Prop $evaluation 'result'
 $value=Get-Prop $remote 'value'
 if ($null -eq $value) { throw 'CDP missing returned value.' }
 return $value
}
function Start-ComfyBrowser {
 # Never claim another pre-existing debug endpoint.
 try { $null=Invoke-RestMethod "$CdpBase/json/version" -TimeoutSec 2; $occupied=$true } catch { $occupied=$false }
 if ($occupied) { throw 'CDP port 9224 already occupied; refusing to attach to an unrelated browser.' }
 $exe=$null
 foreach ($candidate in @('C:\Program Files\Google\Chrome\Application\chrome.exe','C:\Program Files (x86)\Google\Chrome\Application\chrome.exe','C:\Program Files (x86)\Microsoft\Edge\Application\msedge.exe','C:\Program Files\Microsoft\Edge\Application\msedge.exe')) {
  if (Test-Path -LiteralPath $candidate) { $exe=$candidate; break }
 }
 if (-not $exe) { throw 'Existing browser missing; installation forbidden.' }
 $script:BrowserProcess=Start-Process -FilePath $exe -ArgumentList @('--remote-debugging-port=9224','--remote-debugging-address=127.0.0.1',('--user-data-dir="' + $BrowserProfile + '"'),'--no-first-run','--no-default-browser-check',$ComfyBase) -WindowStyle Hidden -PassThru
 $target=$null
 for ($i=0;$i -lt 120;$i++) {
  try {
   $targets=Invoke-RestMethod "$CdpBase/json/list" -TimeoutSec 2
   foreach ($t in $targets) {
    $url=[string](Get-Prop $t 'url')
    if ((Get-Prop $t 'type') -eq 'page' -and $url -match '^http://127\.0\.0\.1:8188(/|$)' -and (Get-Prop $t 'webSocketDebuggerUrl')) { $target=$t; break }
   }
  } catch {}
  if ($null -ne $target) { break }
  Start-Sleep -Milliseconds 500
 }
 if ($null -eq $target) { throw 'Specific ComfyUI CDP target not found.' }
 $script:Socket=[Net.WebSockets.ClientWebSocket]::new()
 $cancel=[Threading.CancellationTokenSource]::new(10000)
 try { $null=$script:Socket.ConnectAsync([uri](Get-Prop $target 'webSocketDebuggerUrl'),$cancel.Token).GetAwaiter().GetResult() } finally { $cancel.Dispose() }
 for ($i=0;$i -lt 80;$i++) {
  $ready=Invoke-Js "Boolean(document.readyState==='complete'&&window.app&&window.app.loadGraphData&&window.app.graphToPrompt)"
  if ($ready -eq $true) { return }
  Start-Sleep -Milliseconds 500
 }
 throw 'ComfyUI frontend readiness timeout.'
}
