function Resolve-Scalar($Graph,$Value,[string]$Class='PrimitiveInt') {
 if ($Value -is [Array]) {
  if ($Value.Count -ne 2 -or [int]$Value[1] -ne 0) { throw 'Invalid scalar link.' }
  $n=Get-Prop $Graph ([string]$Value[0])
  if ((Get-Prop $n 'class_type') -ne $Class) { throw 'Unexpected scalar source.' }
  $Value=Get-Prop (Get-Prop $n 'inputs') 'value'
 }
 if ($null -eq $Value -or $Value -is [Array]) { throw 'Missing literal scalar.' }
 return $Value
}
function Resolve-Dimension($Graph,$Value,[int]$Slot) {
 if ($Value -is [Array]) {
  $n=Get-Prop $Graph ([string]$Value[0])
  if ((Get-Prop $n 'class_type') -eq 'GetImageSize') {
   if ($Value.Count -ne 2 -or [int]$Value[1] -ne $Slot) { throw 'Wrong GetImageSize output slot.' }
   $link=Get-Prop (Get-Prop $n 'inputs') 'image'
   if ($link -isnot [Array] -or $link.Count -ne 2 -or [int]$link[1] -ne 0) { throw 'Invalid image-size source.' }
   $scale=Get-Prop $Graph ([string]$link[0])
   if ((Get-Prop $scale 'class_type') -ne 'ImageScaleToTotalPixels') { throw 'Unexpected image-size source.' }
   $inp=Get-Prop $scale 'inputs'
   if ([string](Get-Prop $inp 'upscale_method') -cne 'nearest-exact' -or [double](Get-Prop $inp 'megapixels') -ne 1 -or [int](Get-Prop $inp 'resolution_steps') -ne 1) { throw 'Official image scale settings differ.' }
   $loadLink=Get-Prop $inp 'image'
   if ($loadLink -isnot [Array] -or $loadLink.Count -ne 2 -or [int]$loadLink[1] -ne 0) { throw 'Invalid scale input link.' }
   $load=Get-Prop $Graph ([string]$loadLink[0])
   if ((Get-Prop $load 'class_type') -ne 'LoadImage' -or (Get-Prop (Get-Prop $load 'inputs') 'image') -cne $InputReferenceName) { throw 'Image dimensions do not originate from BASE.' }
   # Square 1024 BASE + official 1 MP / nearest rounding path.
   return [int]((Get-PngResolution $InputReferencePath).Split('x')[$Slot])
  }
 }
 return (Resolve-Scalar $Graph $Value)
}
function Assert-CompiledPrompt($Graph,[ValidateSet('BASE','EDIT')][string]$Mode,[string]$Prompt) {
 $nodes=@($Graph.PSObject.Properties | ForEach-Object { $_.Value })
 foreach ($spec in @(@('UNETLoader','unet_name',$Model),@('CLIPLoader','clip_name',$Clip),@('VAELoader','vae_name',$Vae),@('KSamplerSelect','sampler_name','euler'),@('Flux2Scheduler','steps',4),@('CFGGuider','cfg',1),@('RandomNoise','noise_seed',$Seed))) {
  $found=@($nodes | Where-Object { (Get-Prop $_ 'class_type') -eq $spec[0] })
  if ($found.Count -ne 1) { throw "Expected one $($spec[0])." }
  $v=Get-Prop (Get-Prop $found[0] 'inputs') $spec[1]
  if ($v -is [Array]) { $v=Resolve-Scalar $Graph $v }
  if ([string]$v -cne [string]$spec[2]) { throw "Frozen parameter mismatch: $($spec[0]).$($spec[1])" }
 }
 foreach ($type in @('SamplerCustomAdvanced','SaveImage','CLIPTextEncode')) {
  if (@($nodes | Where-Object { (Get-Prop $_ 'class_type') -eq $type }).Count -ne 1) { throw "Expected one $type." }
 }
 $encode=@($nodes | Where-Object { (Get-Prop $_ 'class_type') -eq 'CLIPTextEncode' })[0]
 $text=Get-Prop (Get-Prop $encode 'inputs') 'text'
 if ($text -is [Array]) { $text=Resolve-Scalar $Graph $text 'PrimitiveStringMultiline' }
 if ([string]$text -cne $Prompt) { throw 'Literal prompt mismatch.' }
 foreach ($type in @('Flux2Scheduler','EmptyFlux2LatentImage')) {
  $dims=@($nodes | Where-Object { (Get-Prop $_ 'class_type') -eq $type })
  if ($dims.Count -ne 1) { throw "Expected one $type." }
  foreach ($n in $dims) {
   $inp=Get-Prop $n 'inputs'
   $w=Resolve-Dimension $Graph (Get-Prop $inp 'width') 0
   $h=Resolve-Dimension $Graph (Get-Prop $inp 'height') 1
   if ([int]$w -ne 1024 -or [int]$h -ne 1024) { throw 'Effective resolution must be 1024x1024.' }
   $batch=Get-Prop $inp 'batch_size'
   if ($null -ne $batch -and [int]$batch -ne 1) { throw 'Batch size must be 1.' }
  }
 }
 if ($Mode -eq 'EDIT') {
  $loads=@($nodes | Where-Object { (Get-Prop $_ 'class_type') -eq 'LoadImage' })
  if ($loads.Count -ne 1 -or (Get-Prop (Get-Prop $loads[0] 'inputs') 'image') -cne $InputReferenceName) { throw 'Edit must use only exact BASE reference.' }
 }
}
function Normalize-Edit($Graph,[string]$Prompt) {
 $copy=($Graph | ConvertTo-Json -Depth 100 -Compress) | ConvertFrom-Json
 $count=0
 foreach ($p in $copy.PSObject.Properties) {
  $inp=Get-Prop $p.Value 'inputs'
  if ($null -ne $inp) { foreach ($v in $inp.PSObject.Properties) {
   if ($v.Value -is [string] -and $v.Value -ceq $Prompt) { $v.Value='<FROZEN_PROMPT>'; $count++ }
  } }
 }
 if ($count -ne 1) { throw 'Cannot prove single prompt-only difference.' }
 return ($copy | ConvertTo-Json -Depth 100 -Compress)
}
function Get-PngResolution([string]$Path) {
 $b=[IO.File]::ReadAllBytes($Path)
 if ($b.Length -lt 24 -or [BitConverter]::ToString($b[0..7]) -ne '89-50-4E-47-0D-0A-1A-0A') { throw 'Expected PNG.' }
 $w=([long]$b[16]*16777216)+([long]$b[17]*65536)+([long]$b[18]*256)+$b[19]
 $h=([long]$b[20]*16777216)+([long]$b[21]*65536)+([long]$b[22]*256)+$b[23]
 if ($w -ne 1024 -or $h -ne 1024) { throw "Unexpected resolution $w x $h." }
 return '1024x1024'
}
function Execute-Prompt([string]$Label,$Graph,[string]$WorkflowPath) {
 if ($script:Attempts -ge 3) { throw 'Generation cap reached.' }
 $path=Join-Path $OutputDir "$Label.api_prompt.json"
 Write-JsonFile $Graph $path
 $metric=[ordered]@{
  label=$Label; submission='NOT_SENT'; prompt_id=$null; output_path=$null; output_sha256=$null; resolution=$null
  api_prompt_path=$path; api_prompt_sha256=(Get-Sha256 $path); workflow_path=$WorkflowPath; workflow_sha256=(Get-Sha256 $WorkflowPath)
  seed=$Seed; model=$Model; clip=$Clip; vae=$Vae; sampler='euler'; steps=4; cfg=1; scheduler='Flux2Scheduler'
  generation_wall_seconds=$null; peak_process_ram_mib_sampled=$null; peak_system_ram_mib_sampled=$null; peak_gpu_vram_mib_global_sampled=$null
  memory_sample_scope='PROCESS_WHEN_RUNNER_STARTED_COMFY_SYSTEM_AND_WHOLE_FIRST_GPU_NOT_ALLOCATION'
  runtime_error='NOT_VERIFIED'; oom='NOT_VERIFIED'
 }
 $Result.variants[$Label]=$metric
 # Durable consumption BEFORE HTTP. A timeout never permits re-submission.
 $script:Attempts++; $Result.prompt_post_attempts=$script:Attempts
 $Result.uncertain_submission=$true; $metric.submission='ATTEMPT_RECORDED_OUTCOME_UNKNOWN'
 Write-JsonFile $Result $LocalResult
 $body=@{prompt=$Graph;client_id='nexia-one-shot-v1-008'} | ConvertTo-Json -Depth 100 -Compress
 [byte[]]$bytes=$Utf8.GetBytes($body)
 $watch=[Diagnostics.Stopwatch]::StartNew()
 $queue=Invoke-RestMethod -Uri "$ComfyBase/prompt" -Method Post -ContentType 'application/json; charset=utf-8' -Body $bytes -TimeoutSec 30
 $id=[string](Get-Prop $queue 'prompt_id')
 $errors=Get-Prop $queue 'node_errors'
 if ($null -ne $errors -and @($errors.PSObject.Properties).Count -gt 0) { throw 'ComfyUI node validation failure.' }
 if (-not $id) { throw 'Missing prompt_id; outcome unknown; do not retry.' }
 $script:Accepted++; $Result.accepted_prompts=$script:Accepted
 $Result.uncertain_submission=$false; $metric.submission='ACCEPTED'; $metric.prompt_id=$id
 Write-JsonFile $Result $LocalResult
 $entry=$null
 $nvsmi=Get-Command nvidia-smi -ErrorAction SilentlyContinue
 while ($watch.Elapsed.TotalSeconds -lt 900) {
  try {
   $os=Get-CimInstance Win32_OperatingSystem
   $ram=[math]::Round(($os.TotalVisibleMemorySize-$os.FreePhysicalMemory)/1024,0)
   if ($null -eq $metric.peak_system_ram_mib_sampled -or $ram -gt $metric.peak_system_ram_mib_sampled) { $metric.peak_system_ram_mib_sampled=$ram }
   if ($null -ne $script:ComfyProcess) {
    $proc=Get-Process -Id $script:ComfyProcess.Id -ErrorAction Stop
    $ram=[math]::Round($proc.WorkingSet64/1MB,0)
    if ($null -eq $metric.peak_process_ram_mib_sampled -or $ram -gt $metric.peak_process_ram_mib_sampled) { $metric.peak_process_ram_mib_sampled=$ram }
   }
  } catch {}
  if ($null -ne $nvsmi) { try {
   $v=(& $nvsmi.Source --query-gpu=memory.used --format=csv,noheader,nounits 2>$null | Select-Object -First 1)
   if ($v -match '^\s*(\d+)') {
    $gpu=[int]$matches[1]
    if ($null -eq $metric.peak_gpu_vram_mib_global_sampled -or $gpu -gt $metric.peak_gpu_vram_mib_global_sampled) { $metric.peak_gpu_vram_mib_global_sampled=$gpu }
   }
  } catch {} }
  # Read-only completion polling, never a generation retry. Read failure stops.
  $history=Invoke-RestMethod "$ComfyBase/history/$id" -TimeoutSec 5
  $entry=Get-Prop $history $id
  if ($null -ne $entry) {
   Write-JsonFile $entry (Join-Path $OutputDir "$Label.history.json")
   $status=Get-Prop $entry 'status'
   if ((Get-Prop $status 'status_str') -eq 'error') {
    $metric.runtime_error='RECORDED'
    if (($entry | ConvertTo-Json -Depth 100) -match 'out of memory|OutOfMemory|CUDA.*OOM') { $metric.oom='RECORDED' }
    throw "ComfyUI runtime error: $Label; inspect saved history."
   }
   if ((Get-Prop $status 'completed') -eq $true) { break }
  }
  Start-Sleep -Seconds 1
 }
 if ($null -eq $entry -or (Get-Prop (Get-Prop $entry 'status') 'completed') -ne $true) { throw 'Completion timeout; no retry.' }
 $images=@(); $outputs=Get-Prop $entry 'outputs'
 if ($null -ne $outputs) { foreach ($p in $outputs.PSObject.Properties) {
  $imgs=Get-Prop $p.Value 'images'; if ($null -ne $imgs) { $images+=@($imgs) }
 } }
 if ($images.Count -ne 1) { throw 'Expected exactly one saved image.' }
 $image=$images[0]
 $q="filename=$([uri]::EscapeDataString([string](Get-Prop $image 'filename')))&subfolder=$([uri]::EscapeDataString([string](Get-Prop $image 'subfolder')))&type=$([uri]::EscapeDataString([string](Get-Prop $image 'type')))"
 $dest=Join-Path $OutputDir "$Label.png"
 Invoke-WebRequest "$ComfyBase/view?$q" -UseBasicParsing -OutFile $dest -TimeoutSec 30
 $watch.Stop()
 $metric.output_path=$dest; $metric.output_sha256=Get-Sha256 $dest; $metric.resolution=Get-PngResolution $dest
 $metric.generation_wall_seconds=[math]::Round($watch.Elapsed.TotalSeconds,3)
 $metric.runtime_error='NONE_RECORDED_IN_COMPLETED_HISTORY'; $metric.oom='NONE_RECORDED_IN_COMPLETED_HISTORY'
 $script:Completed++; $Result.completed_generations=$script:Completed
 Write-JsonFile $Result $LocalResult
 return $metric
}
function Publish-RawResult {
 Test-RemoteAbsent
 $json=[IO.File]::ReadAllText($LocalResult,$Utf8)
 $payload=@{message='Record ONE-SHOT V1 bounded FLUX raw result';content=[Convert]::ToBase64String($Utf8.GetBytes($json))}
 $payloadPath=Join-Path $OutputDir 'github-writeback-payload.json'
 Write-JsonFile $payload $payloadPath
 # No sha field: create-only. Racing writers cause failure, never overwrite.
 $null=Invoke-Gh -GhArgs @('api','--method','PUT',"repos/$Repo/contents/$RawResultRepoPath",'--input',('"' + $payloadPath + '"'))
 $remote=Invoke-Gh -GhArgs @('api',"repos/$Repo/contents/$RawResultRepoPath")
 $decoded=$Utf8.GetString([Convert]::FromBase64String([string](Get-Prop $remote 'content')))
 if ($decoded -cne $json) { throw 'GitHub readback mismatch.' }
 # Separate receipt: raw payload cannot truthfully contain its own future readback.
 Write-JsonFile @{status='PASS_GH_API_READBACK_MATCH';raw_blob_sha=(Get-Prop $remote 'sha');local_sha256=(Get-Sha256 $LocalResult)} (Join-Path $OutputDir 'WRITEBACK_RECEIPT.json')
}
function Cleanup-Runner {
 if ($null -ne $script:Socket) { $script:Socket.Dispose() }
 if ($null -ne $script:BrowserProcess) {
  $owned=Get-CimInstance Win32_Process | Where-Object { $null -ne $_.CommandLine -and $_.CommandLine.Contains($BrowserProfile) }
  foreach ($p in $owned) { Stop-Process -Id $p.ProcessId -Force -ErrorAction SilentlyContinue }
 }
 if ($null -ne $script:ComfyProcess -and -not $script:ComfyProcess.HasExited) { Stop-Process -Id $script:ComfyProcess.Id -Force -ErrorAction SilentlyContinue }
 # Keep reference, profile and lock for diagnostics; no recursive deletion.
}
New-Item -ItemType Directory -Path $OutputDir -Force | Out-Null
$LocalResult=Join-Path $OutputDir 'RAW_RESULT.json'
$lockPath=Join-Path $OutputDir 'ONE_SHOT_008.lock'
$lock=$null; $stage='PRECHECK'; $exitCode=1
try {
 $lock=[IO.File]::Open($lockPath,[IO.FileMode]::CreateNew,[IO.FileAccess]::Write,[IO.FileShare]::None)
 $gh=Get-Command gh -ErrorAction Stop; $GhExe=$gh.Source
 Test-RemoteAbsent; $script:MayPublish=$true
 foreach ($p in @($PythonExe,$ComfyMain,(Join-Path $ComfyRoot "models\diffusion_models\$Model"),(Join-Path $ComfyRoot "models\text_encoders\$Clip"),(Join-Path $ComfyRoot "models\vae\$Vae"))) {
  if (-not (Test-Path -LiteralPath $p)) { throw 'Required existing component missing. No installation allowed.' }
 }
 if (Test-Path -LiteralPath $InputReferencePath) { throw 'Reference already exists; no overwrite.' }
 $version=[IO.File]::ReadAllText((Join-Path $ComfyRoot 'comfyui_version.py'))
 if ($version -notmatch "__version__\s*=\s*['""]0\.39\.0['""]") { throw 'Existing ComfyUI must be 0.39.0.' }
 Write-JsonFile ($T2IText | ConvertFrom-Json) (Join-Path $OutputDir 'official-t2i.json')
 Write-JsonFile ($EditText | ConvertFrom-Json) (Join-Path $OutputDir 'official-edit.json')
 $stage='START_COMFY'; Start-Comfy
 $stage='START_FRONTEND'; Start-ComfyBrowser
 $stage='COMPILE_BASE'
 $base=Compile-Workflow -TemplateText $T2IText -Mode BASE -Prompt $BasePrompt -InputImageName ''
 Assert-CompiledPrompt $base.output BASE $BasePrompt
 $baseWorkflow=Join-Path $OutputDir 'BASE.workflow.json'; Write-JsonFile $base.workflow $baseWorkflow
 $stage='GENERATE_BASE'; $bm=Execute-Prompt BASE $base.output $baseWorkflow
 $stage='BASE_HUMAN_GATE'
 $Result.base_human_gate='WAITING_FOR_KAEL'
 Write-JsonFile $Result $LocalResult
 Start-Process -FilePath $bm.output_path | Out-Null
 Write-Host 'SI solo si BASE cumple SEIS condiciones: 1 caja; cuerpo azul oscuro mate; tapa negra; sin personas/manos; sin otro producto; sin texto prominente.'
 $answer=(Read-Host 'SI para B1/B2; cualquier otra respuesta detiene el experimento').Trim().ToUpperInvariant()
 if ($answer -ne 'SI') { $Result.base_human_gate='FAIL'; $Result.status='BASE_PRECONDITION_FAIL'; throw 'BASE_PRECONDITION_FAIL' }
 $Result.base_human_gate='PASS_KAEL_CONFIRMED'
 [IO.File]::Copy($bm.output_path,$InputReferencePath,$false)
 $script:InputCreated=$true
 $baseHash=Get-Sha256 $InputReferencePath
 if ($baseHash -cne $bm.output_sha256) { throw 'BASE reference hash mismatch.' }
 $Result['reference_sha256']=$baseHash
 $stage='COMPILE_B1_B2'
 $b1=Compile-Workflow -TemplateText $EditText -Mode EDIT -Prompt $B1Prompt -InputImageName $InputReferenceName
 $b2=Compile-Workflow -TemplateText $EditText -Mode EDIT -Prompt $B2Prompt -InputImageName $InputReferenceName
 Assert-CompiledPrompt $b1.output EDIT $B1Prompt; Assert-CompiledPrompt $b2.output EDIT $B2Prompt
 if ((Normalize-Edit $b1.output $B1Prompt) -cne (Normalize-Edit $b2.output $B2Prompt)) { throw 'B1/B2 differ beyond prompt.' }
 $Result.b1_b2_equivalence='PASS_EXACT_NORMALIZED_API_GRAPH'
 $w1=Join-Path $OutputDir 'B1.workflow.json'; $w2=Join-Path $OutputDir 'B2.workflow.json'
 Write-JsonFile $b1.workflow $w1; Write-JsonFile $b2.workflow $w2
 $stage='GENERATE_B1'
 if ((Get-Sha256 $InputReferencePath) -cne $baseHash) { throw 'BASE changed before B1.' }
 $null=Execute-Prompt B1 $b1.output $w1
 $stage='GENERATE_B2'
 if ((Get-Sha256 $InputReferencePath) -cne $baseHash) { throw 'BASE changed before B2.' }
 $null=Execute-Prompt B2 $b2.output $w2
 if ((Get-Sha256 $InputReferencePath) -cne $baseHash) { throw 'BASE changed during B2.' }
 $Result.status='EXECUTION_COMPLETE_VISUAL_QA_PENDING'; $exitCode=0
} catch {
 if ($Result.status -eq 'STARTED') { $Result.status='STOPPED_FAIL_CLOSED' }
 $Result.error_stage=$stage; $Result.error=$_.Exception.Message
 Write-Host "STOP: $stage | $($Result.error)"
} finally {
 # Failed lock acquisition must not alter earlier attempt evidence.
 if ($null -ne $lock) {
  try {
   $Result.finished_at=(Get-Date).ToString('o')
   $Result.writeback='PAYLOAD_PENDING_VERIFICATION_SEE_SEPARATE_RECEIPT'
   Write-JsonFile $Result $LocalResult
   if ($script:MayPublish) {
    try { Publish-RawResult; Write-Host 'RAW_RESULT_WRITEBACK: PASS_GH_API_READBACK_MATCH' }
    catch {
     $exitCode=1
     Write-JsonFile @{status='FAIL_OR_UNKNOWN';message=$_.Exception.Message;no_retry=$true} (Join-Path $OutputDir 'WRITEBACK_RECEIPT.json')
     Write-Host 'RAW_RESULT_WRITEBACK: FAIL_OR_UNKNOWN. No retry; inspect local receipt.'
    }
   }
  } finally { Cleanup-Runner; $lock.Dispose() }
  Write-Host "LOCAL_RESULT: $LocalResult"
  Write-Host "POST_ATTEMPTS: $script:Attempts | ACCEPTED: $script:Accepted | COMPLETED: $script:Completed"
 }
}
exit $exitCode

